  "공통 설정": "Общие настройки",
  "입니다. 표시·아이콘·사용 패턴은 좌측 [뷰어 — TY Viewer]/[뷰어 — In Viewer] 탭에서 뷰어별로 설정하며, 기능은 두 뷰어 동일합니다.": ". Отображение·значки·паттерны использования настраиваются по просмотрщикам во вкладках [Просмотрщик — TY Viewer]/[Просмотрщик — In Viewer] слева; функции обоих одинаковы.",
  "영상 파이프라인": "Конвейер изображений",
  "WASM 디코딩 파이프라인 (베타) — 원본 픽셀(WADO-RS bulkdata)을 브라우저에서 직접 디코딩": "Конвейер WASM-декодирования (бета) — прямое декодирование исходных пикселей (WADO-RS bulkdata) в браузере",
  "켜면 2D 뷰어가 서버 렌더링(JPEG) 대신 원본 16bit 프레임을 받아 WASM 코덱으로 디코딩합니다. W/L 조정이 서버 왕복 없이 즉시 반영되고, 병원 설정의 전송구문(JPEG2000/JPEG-LS)으로 수신합니다. 디코딩 전에는 서버 렌더링으로 표시(자동 폴백).": "При включении 2D-просмотрщик получает исходные 16-битные кадры вместо серверного рендеринга (JPEG) и декодирует их WASM-кодеком. W/L меняется мгновенно без обращения к серверу; приём в transfer syntax из настроек больницы (JPEG2000/JPEG-LS). До декодирования показывается серверный рендер (автофолбэк).",
  "제품 모드 프로파일 (05 Mode Profile — 서버 JSON)": "Профиль режима продукта (05 Mode Profile — серверный JSON)",
  "모드 선택…": "Выбор режима…",
  "현재 적용": "Сейчас применён",
  "모드 적용 — 왼쪽 ⟳ Refresh로 즉시 확인": "Режим применён — проверьте сразу через ⟳ Refresh слева",
  "현재 워크리스트·뷰어 레이아웃(컬럼·검색필드·팔레트/썸네일 배치·선택 뷰어)을 선택한 프로파일에 저장 (전역)": "Сохранить текущую компоновку рабочего списка и просмотрщика (колонки·поля поиска·палитра/миниатюры·выбранный просмотрщик) в выбранный профиль (глобально)",
  "저장할 프로파일을 먼저 선택하세요": "Сначала выберите профиль для сохранения",
