  "프로파일에 저장할까요? (전역 — 모든 사용자에게 적용)": "сохранить в профиль? (глобально — для всех пользователей)",
  "프로파일에 저장했습니다 (전역)": "сохранено в профиль (глобально)",
  "현재 화면을 프로파일에 저장": "Сохранить текущий экран в профиль",
  "Core 기능은 동일, 화면 구성(컬럼·검색필드·팔레트/썸네일 배치·더블클릭·선택 뷰어)만 제품별 프로파일로 전환 — 타 PACS 사용 경험 그대로 이전. 프로파일 정의는 서버 전역 설정(mode.profiles)에서 로드.": "Функции Core одинаковы; профиль продукта переключает только конфигурацию экрана (колонки·поля поиска·палитра/миниатюры·двойной клик·выбранный просмотрщик) — перенос опыта работы с другими PACS. Определения профилей загружаются из глобальных настроек сервера (mode.profiles).",
  "=INFINITT 스타일 레이아웃 저장소 ·": "=хранилище раскладок в стиле INFINITT ·",
  "=자체 뷰어 레이아웃.": "=раскладка собственного просмотрщика.",
