  "모든 뷰어(SaintView·T-View·I-View)의 워크리스트와": "к рабочим спискам всех просмотрщиков (SaintView·T-View·I-View) и",
  "Live 모드에도 함께": "к режиму Live тоже",
  "적용됩니다. 수동일 때 원격에 변경이 생기면 목록을 바꾸지 않고 상단에 알림만 띄웁니다.": "применяется. В ручном режиме при изменениях на удалённой стороне список не меняется — только уведомление сверху.",
  "초는 매우 짧습니다 — Live 모드에서는 원격 PACS 에 그만큼 자주 질의합니다.": "с — очень мало: в режиме Live удалённый PACS будет опрашиваться так же часто.",
  "워크리스트: Enter=View&Draft · B=일괄검토 · E=Emergency │ 뷰어: ←→ 이미지 · I 반전 · R 회전 · F Fit · L Link · 1/2/4 분할 · Space Cine · Esc 닫기": "Рабочий список: Enter=View&Draft · B=пакетная проверка · E=Emergency │ Просмотрщик: ←→ изображения · I инверсия · R поворот · F Fit · L Link · 1/2/4 раскладка · Space Cine · Esc закрыть",
