  "최근 환자 순": "в порядке недавних пациентов",
  "으로 훑어 시리즈 썸네일 → 각 시리즈의 이미지 순서로 미리 받아 둡니다. 저장 위치는 브라우저 전용 영역이라": "— миниатюры серий → изображения каждой серии скачиваются заранее. Хранилище — выделенная область браузера, поэтому",
  "탐색기에 보이지 않고 권한 프롬프트도 없습니다": "не видно в проводнике и нет запросов разрешений",
  ". 받아 둔 검사는 서버 왕복 없이 열립니다.": ". Скачанные исследования открываются без обращения к серверу.",
  "⚠ 현재는": "⚠ Сейчас работает только в",
  "Live 모드 + 2D 뷰어(SaintView·T-View·I-View)": "режиме Live + 2D-просмотрщиках (SaintView·T-View·I-View)",
  "에서만 동작합니다. W/L 을 조정하는 동안에는 서버 렌더로 자동 폴백합니다(저장본은 검사 기본 W/L 로 구운 영상이라 그대로 쓰면 표시 W/L 과 실제 영상이 어긋납니다).": ". Во время настройки W/L автоматический фолбэк на серверный рендер (кэш записан с W/L по умолчанию — иначе отображаемый W/L разойдётся с изображением).",
  "로그아웃·세션 만료 시 받아 둔 영상은 전부 삭제됩니다": "При выходе или истечении сессии все скачанные изображения удаляются",
