  "상한 근접 알림": "Уведомление о приближении к лимиту",
  "사용량이": "Если использование превышает",
  "% 를 넘으면 알립니다 —": "% — уведомление —",
  "다운로드가 곧 중지될 때만": "только когда загрузка скоро остановится",
  "뜹니다(자동 삭제가 꺼져 있거나, 열려 있는 검사만으로 상한을 넘어 지울 것이 없을 때). 자동 삭제가 정상 작동 중이면 사용량이 상한에 붙어 있는 것이 정상이라 알리지 않습니다. 워크리스트 창에서 1회 — 판독 중인 뷰어 창에는 띄우지 않습니다.": "показывается (когда автоудаление выключено или открытые исследования сами превышают лимит и удалять нечего). При работающем автоудалении использование у лимита — норма, уведомления нет. Один раз в окне рабочего списка — не в окне просмотрщика во время описания.",
