  "워크리스트 탭의 상용구 관리": "в управлении шаблонными фразами вкладки Рабочий список",
  "또는 워크리스트 하단 상용구(Std) 패널에서. 더블클릭 또는 Alt+단축키로 Conclusion에 삽입됩니다.": "или в панели шаблонных фраз (Std) внизу рабочего списка. Вставка в Conclusion двойным кликом или Alt+клавишей.",
  "리포트 구성 (Report Composition — UBPACS p.22)": "Состав отчёта (Report Composition — UBPACS стр.22)",
  "AI Structured Report 패널 표시 (해제 시 Report 단독 — AI는 ↗ 별도 창으로만)": "Показ панели AI Structured Report (при снятии — только Report, AI лишь в отдельном окне ↗)",
  "AI 초안을 Report에 자동 적용 (해제 시 빈 양식에서 시작 — [적용 ▶]로만 가져옴)": "Автоприменение AI-черновика в Report (при снятии — старт с пустой формы, только через [Применить ▶])",
  "리포트 패널: ◀▶ 이전/다음 환자 이동 · 이력 콤보(과거 버전 보기) · ↗ AI 별도 창(모니터) — 계정 로밍.": "Панель отчёта: ◀▶ предыдущий/следующий пациент · комбобокс истории (прежние версии) · ↗ AI в отдельном окне (мониторе) — роуминг учётной записи.",
  "출력 형식": "Форматы вывода",
  "PDF · DICOM SR(확정 후 전송) · FHIR DiagnosticReport": "PDF · DICOM SR (отправка после утверждения) · FHIR DiagnosticReport",
  "OHIF (고급 웹뷰어)": "OHIF (расширенный веб-просмотрщик)",
  "OHIF 사용": "Использовать OHIF",
  "OHIF 아이콘 표시·동작 허용 (기본 꺼짐)": "Показ значков OHIF и разрешение действий (по умолчанию выкл.)",
  "끄면 워크리스트(⌂ Adv·🌐·우클릭 메뉴)와 뷰어의 OHIF 버튼이 숨겨지고 동작하지 않습니다. 더블클릭 동작이 OHIF 로 설정돼 있어도 자체 뷰어로 열립니다.": "При выключении кнопки OHIF в рабочем списке (⌂ Adv·🌐·контекстное меню) и просмотрщике скрываются и не работают. Даже если двойной клик настроен на OHIF, откроется собственный просмотрщик.",
  "Tools 아이콘 크기 (TY · In 뷰어)": "Размер значков Tools (TY · In просмотрщики)",
  "두 뷰어의 도구 팔레트 아이콘 크기를 한 곳에서 조정합니다 (각 뷰어 전용 탭에서도 동일하게 조정 가능).": "Размер значков палитры инструментов обоих просмотрщиков настраивается здесь (то же доступно во вкладках каждого просмотрщика).",
  "OK(저장)": "OK (сохранить)",
  "후 열려 있는 뷰어를 새로고침하면 반영됩니다.": "— затем обновите открытые просмотрщики, чтобы применить.",
  "In Viewer 전용": "Только In Viewer",
  "표시·아이콘·사용 패턴 설정은 뷰어별로 적용되고, 판독·측정 등 기능은 두 뷰어 동일합니다.": "Отображение·значки·паттерны использования применяются по просмотрщикам; функции описания, измерений и др. у обоих одинаковы.",
  "(이 뷰어 전용 — 모달리티 → Series / Image)": "(только этот просмотрщик — модальность → Series / Image)",
  "이 뷰어 전용 2D Layout. 맘모(MG)는 뷰어 공통 규정이라 여기 없습니다.": "2D Layout только этого просмотрщика. Маммография (MG) — общее правило просмотрщиков, здесь её нет.",
  "⚠ 뷰어 공통의": "⚠ В общих настройках просмотрщиков",
  "이 공통 설정을 모든 뷰어에 우선 적용": "Применять эти общие настройки приоритетно ко всем просмотрщикам",
  "이 켜져 있어": "включено, поэтому",
  "이 설정은 무시": "эта настройка игнорируется",
  "됩니다. 사용하려면 뷰어 공통에서 그 체크를 해제하세요.": ". Чтобы использовать, снимите ту отметку в общих настройках просмотрщиков.",
