  "2X2 (기본)": "2X2 (по умолчанию)",
  "멀티선택 색": "Цвет мультивыбора",
  "Crosslink 멀티 선택 페인 테두리 색": "Цвет рамки ячеек мультивыбора Crosslink",
  "Shift/Ctrl/A 로 선택된 페인 테두리 (기본 자주색)": "Рамка ячеек, выбранных Shift/Ctrl/A (по умолчанию пурпурная)",
  "오버레이 글자": "Шрифт оверлея",
  "판독 도크": "Док описания",
