  "두 번째부터는 캐시로 빨라집니다(⑤ 참고).": "Со второго раза быстрее за счёт кэша (см. ⑤).",
  "🔴 **서버 gzip 이 꺼져 있습니다** — 앱 번들이 무압축으로 전송됩니다(약 4배).": "🔴 **gzip сервера выключен** — бандл приложения передаётся без сжатия (~4x).",
