  "포트는 병원마다 자동 배정(상이)됩니다. ⚠ 단일 Orthanc는 DICOM 포트가 하나라, 실제 병원별 포트 리스닝은 병원별 Orthanc 인스턴스 또는 DICOM 라우터 배치가 필요합니다(여기서는 구성·연결 점검).": "Порты назначаются автоматически для каждой больницы (различаются). ⚠ У единственного Orthanc один DICOM-порт — для реального прослушивания портов по больницам нужны отдельные экземпляры Orthanc или DICOM-роутер (здесь — конфигурация и проверка соединения).",
  "🩻 검사 배정": "🩻 Назначение исследований",
  "수신 AET가 등록 장비와 매칭되지 않아 병원이 비어있는(미배정) 검사를 이 병원에 귀속합니다. (Client 뷰어는 로그인한 병원의 검사만 표시하므로, 미배정 검사는 배정해야 보입니다.)": "Исследования без больницы (AET приёма не совпал с зарегистрированными аппаратами) привязываются к этой больнице. (Client-просмотрщик показывает только исследования больницы входа — неназначенные видны лишь после назначения.)",
