  "Hanging Protocol — 규칙 선택 · '직접설정'으로 지금 화면을 새 프로토콜로 저장 (관리: Setting>행잉(HP))": "Hanging Protocol — выбор правила · через «Ручная настройка» текущий экран сохраняется как новый протокол (управление: Setting>Hanging (HP))",
