  "등록된 규칙 없음 — 아래 '직접설정'으로 지금 화면을 저장할 수 있습니다": "Нет зарегистрированных правил — текущий экран можно сохранить через «Ручная настройка» ниже",
  "지금 뷰어에 잡아 둔 화면(모니터·Series/Image 레이아웃·칸별 영상)을 새 프로토콜로 저장합니다": "Текущий экран просмотрщика (монитор·раскладка Series/Image·изображения по ячейкам) сохраняется как новый протокол",
  "직접설정 — 지금 화면을 프로토콜로 저장": "Ручная настройка — сохранить текущий экран как протокол",
  "프로토콜명 (예: 흉부 비교 2×2)": "Имя протокола (напр.: сравнение груди 2×2)",
  "켜면 조건(장비)이 맞는 검사를 열 때 자동으로 이 배치가 적용됩니다. 꺼져 있으면 이 드롭다운에서 골라야 적용됩니다": "При включении эта расстановка применяется автоматически к исследованиям с совпадающим условием (аппаратом). При выключении — только выбором в этом списке",
  "Exam 열 때 자동 적용": "Автоприменение при открытии Exam",
  "여러 규칙이 걸릴 때 이 규칙을 가장 먼저 검사합니다": "При нескольких подходящих правилах это проверяется первым",
  "기존": "Существующий",
  "을 덮어씁니다 — 화면 배치·장비·W/L·링크 4종(전체 링크·스크롤 동기화·Cross Link·Scout)이": "будет перезаписан — расстановка экрана·аппарат·W/L·4 связи (общая связь·синхронизация прокрутки·Cross Link·Scout) заменятся",
  "지금 화면 값": "значениями текущего экрана",
  "으로 바뀝니다. 부위·출처·Projection·설명은 유지되고, 위 두 체크박스는 기존 값을 불러왔습니다.": ". Область·источник·Projection·описание сохраняются; два чекбокса выше загружены из прежних значений.",
  "저장되는 것: 이 모니터 · Series/Image 레이아웃 · 칸별 시리즈 · 칸별 과거검사 기간. 3D 창과 다른 모니터 창의 구성은 저장되지 않습니다(같은 이름으로 각 창에서 저장하면 합쳐집니다).": "Сохраняется: этот монитор · раскладка Series/Image · серии по ячейкам · периоды предыдущих исследований по ячейкам. Конфигурации 3D-окна и окон других мониторов не сохраняются (сохранение под тем же именем из каждого окна объединяет их).",
