  "저장 상한에 도달했습니다 — 자동 삭제가 꺼져 있어 더 받지 않습니다.": "Достигнут лимит хранения — автоудаление выключено, загрузка прекращена.",
  "열려 있는 검사만으로 저장 상한을 넘었습니다 — 설정 > 환경 > 영상 취득에서 [지금 비우기] 를 누르거나 저장 상한을 올려야 이어받습니다.": "Открытые исследования сами превышают лимит хранения — чтобы продолжить, нажмите [Очистить сейчас] в Настройки > Среда > Получение изображений или увеличьте лимит.",
  "저장 상한에 도달했습니다 — 보고 있는 검사는 지우지 않으므로, 뷰어 창을 닫거나 상한을 늘리면 이어받습니다.": "Достигнут лимит хранения — просматриваемые исследования не удаляются; закройте окна просмотрщика или увеличьте лимит, чтобы продолжить.",
  "뷰어 창이 별도 포트(VITE_VIEWER_BASE)로 뜨는 배치입니다 — 창끼리 저장소를 공유할 수 없어 사용할 수 없습니다.": "Окно просмотрщика открывается на отдельном порту (VITE_VIEWER_BASE) — окна не могут делить хранилище, функция недоступна.",
  "보안 컨텍스트(HTTPS 또는 localhost)가 아닙니다 — 브라우저가 OPFS 를 막습니다.": "Не защищённый контекст (HTTPS или localhost) — браузер блокирует OPFS.",
  "이 브라우저는 OPFS(navigator.storage.getDirectory)를 지원하지 않습니다.": "Этот браузер не поддерживает OPFS (navigator.storage.getDirectory).",
  "이 브라우저는 IndexedDB 를 지원하지 않습니다(저장 인덱스에 필요).": "Этот браузер не поддерживает IndexedDB (нужен для индекса хранилища).",
  "이 브라우저는 Window Management API(모니터 감지)를 지원하지 않습니다 — 최신 Chrome/Edge 를 사용하세요.": "Этот браузер не поддерживает Window Management API (обнаружение мониторов) — используйте свежий Chrome/Edge.",
