  "초대 시 자동으로 줄 기본 권한": "Права по умолчанию при приглашении",
  "여기서 정한 것은 기본값입니다. 협진 중에는 협진 페이지에서 참가자마다 켜고 끌 수 있습니다.": "Это значения по умолчанию. Во время сеанса их можно менять для каждого участника на панели совместного просмотра.",
  "판독 수정·영상 삭제는 협진으로 절대 위임되지 않습니다 — 목록에 없는 이유입니다.": "Редактирование описания и удаление изображений никогда не делегируются — поэтому их нет в списке.",
  "화면 조작 · 발표자": "Управление экраном · Докладчик",
  "참가 시 발표자 화면 따라가기 (내가 화면을 만지면 자유 보기로 전환)": "Следовать за докладчиком при входе (при изменении вида — свободный просмотр)",
  "참가자의 권한 요청을 자동 승인": "Автоматически одобрять запросы прав участников",
  "화면 조작(줌·팬·W/L)은 발표자 1명만 전원에게 송출합니다. 나머지 참가자는 각자 자유롭게 보며, 주석·커서는 항상 전원에게 공유됩니다.": "Управление экраном (масштаб/панорама/W-L) транслирует только докладчик. Остальные смотрят свободно; разметка и курсоры всегда видны всем.",
  "참여자 표시": "Отображение участников",
  "마우스 커서 옆에 참여자 아이디 표시": "Показывать ID участника рядом с курсором",
  "참여자별 색으로 커서·툴·글자 구분": "Различать курсор, инструменты и текст по цвету участника",
  "화상·음성 네트워크 (STUN/TURN)": "Сеть видео/аудио (STUN/TURN)",
  "병원 내부망은 비워 두면 됩니다. 인터넷을 건너는 협진에만 STUN/TURN 을 넣으세요 (JSON 배열).": "Во внутренней сети больницы оставьте пустым. STUN/TURN нужен только для сеансов через интернет (массив JSON).",
  "계측·주석 그리기 (세션 한정 — 판독에는 Master 채택 시에만 저장)": "Рисовать измерения и разметку (только в сеансе — в описание попадёт лишь принятое Master)",
  "텍스트·글쓰기 (세션 한정)": "Текст и надписи (только в сеансе)",
  "검사 탭 전환·과거 검사 열기": "Переключать вкладки исследований и открывать предыдущие",
  "적용 순서(고정)": "Порядок применения (фиксированный)",
  ": ① 행잉(HP — 선택 시만) → ② Mammo(2D-MG — 선택 시만) → ③ 이 Common 표 → ④ 각 뷰어별 표 → ⑤ 자동 규칙(1×1 등).": ": ① Протокол (HP — только если выбран) → ② Маммо (2D-MG — только если включён) → ③ эта таблица Common → ④ таблица просмотрщика → ⑤ автоправила (1×1 и т.д.).",
  "이 표에 해당 모달리티 행이 있으면 세 뷰어(SaintView/I-View/T-View) 모두 이 값을 씁니다. 행이 없으면 그 뷰어의 개별 표를 봅니다.": "Если в этой таблице есть строка для модальности, все три просмотрщика (SaintView/I-View/T-View) используют её. Если нет — используется таблица данного просмотрщика.",
  "규정이 켜져 있을 때만 그 규정을 따릅니다(이 표에 MG 행이 없는 이유).": "действует только когда это правило включено (поэтому в таблице нет строки MG).",
  "행은 그 표에 행이 없는 나머지 모달리티에 적용됩니다 —": "строка применяется к остальным модальностям, отсутствующим в той таблице —",
  "적용 순서(고정): Common 표에 그 모달리티 행이 있으면 Common 이 우선하고, 없을 때 이 표가 적용됩니다.": "Порядок (фиксированный): если в таблице Common есть строка для модальности, приоритет у Common; эта таблица применяется только при её отсутствии.",
  ")는 아래": ") подчиняется правилу",
  "별도 창으로 크게 보기 (다른 모니터로 옮길 수 있습니다)": "Открыть в отдельном окне (можно перенести на другой монитор)",
  "팝업이 차단되었습니다 — 이 사이트의 팝업을 허용해 주세요": "Всплывающее окно заблокировано — разрешите всплывающие окна для этого сайта",
  "협진 패널 숨기기 (오른쪽으로 접기)": "Скрыть панель совместного просмотра (свернуть вправо)",
