  "드래그하면 폭이 바뀝니다 (더블클릭 = 기본 폭)": "Потяните, чтобы изменить ширину (двойной щелчок — по умолчанию)",
  "좌우 비율 무시": "Игнорировать соотношение Л/П",
  "조직 탐지와 무관하게 항상 같은 고정 비율로 가운데 여백 제거 (기본 켬)": "Всегда обрезать центральный зазор с одинаковым фиксированным соотношением, независимо от детекции ткани (вкл. по умолчанию)",
  "자동 탐지가 영상마다 실패·지연하면 배치가 들쭉날쭉해집니다 — 켜 두면 항상 같은 모양으로 나옵니다. 해제하면 아래 흉벽 판정(자동 탐지) 규칙을 씁니다.": "Если автодетекция на части снимков не срабатывает или запаздывает, компоновка становится неровной — включите для стабильного вида. Снимите флажок, чтобы использовать правила определения грудной стенки ниже.",
  "드래그 = 컬럼 위치 이동 · 오른쪽 가장자리 드래그 = 폭 조절": "Перетаскивание = переместить столбец · за правый край = изменить ширину",
