  "행 드래그 = 순서 이동": "Перетащите строку = изменить порядок",
  "워크리스트 항목 구성 — 표시·검색·순서 (그리드와 같은 계정별 저장)": "Элементы списка — показ, поиск, порядок (то же хранение по учётной записи, что и сетка)",
